var allResults = workflowContext.actions.Capture_All_Results.outputs || [];
var flattened = [];
for (var i = 0; i < allResults.length; i++) {
    var chunk = allResults[i];
    if (chunk && chunk.rows && Array.isArray(chunk.rows)) {
        for (var j = 0; j < chunk.rows.length; j++) {
            flattened.push(chunk.rows[j]);
        }
    }
}
return flattened;

var rows = workflowContext.actions.Transform_Query_Results_To_Rows.outputs.body;
var grouped = {};
for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    var key = [row.ProductId, row.Luma, row.Workspace, row.DeploymentName, row.ModelName, row.AccountName, row.SubscriptionId, row.SkuName, row.SkuCapacity, row.BackendId, row.Endpoint].join('|');
    if (!grouped[key]) {
        grouped[key] = {
            ProductId: row.ProductId,
            Luma: row.Luma,
            Workspace: row.Workspace,
            DeploymentName: row.DeploymentName,
            ModelName: row.ModelName,
            AccountName: row.AccountName,
            SubscriptionId: row.SubscriptionId,
            SkuName: row.SkuName,
            SkuCapacity: row.SkuCapacity,
            BackendId: row.BackendId,
            Endpoint: row.Endpoint,
            PromptTokens: 0,
            CompletionTokens: 0,
            TotalTokens: 0,
            Calls: 0,
            FirstSeen: row.FirstSeen,
            LastSeen: row.LastSeen,
            Regions: [],
            CallerIpAddresses: []
        };
    }
    var g = grouped[key];
    g.PromptTokens += (row.PromptTokens || 0);
    g.CompletionTokens += (row.CompletionTokens || 0);
    g.TotalTokens += (row.TotalTokens || 0);
    g.Calls += (row.Calls || 0);
    if (row.FirstSeen && (!g.FirstSeen || row.FirstSeen < g.FirstSeen)) g.FirstSeen = row.FirstSeen;
    if (row.LastSeen && (!g.LastSeen || row.LastSeen > g.LastSeen)) g.LastSeen = row.LastSeen;
    var mergeSet = function(t, s, l) { if (!s) return; var a = Array.isArray(s) ? s : [s]; for (var j = 0; j < a.length && t.length < l; j++) { if (a[j] && t.indexOf(a[j]) === -1) t.push(a[j]); } };
    mergeSet(g.Regions, row.Regions, 8);
    mergeSet(g.CallerIpAddresses, row.CallerIpAddresses, 8);
}
var result = [];
for (var k in grouped) result.push(grouped[k]);
result.sort(function(a, b) { return (b.TotalTokens || 0) - (a.TotalTokens || 0); });
return result;
